perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @ENTITIES = qw(User Memo Attachment IdentityProvider Inbox InstanceSetting MemoRelation MemoShare Reaction UserIdentity UserSetting);
my %hits; # type -> pkg -> {files}

sub is_store {
  my ($p) = @_;
  $p =~ s{^\Q$REPO\E/?}{};
  return ($p eq "store" || $p =~ m{^store/});
}

sub pkg_of {
  my ($fp) = @_;
  (my $d = $fp) =~ s{/[^/]+$}{};
  $d =~ s{^\Q$REPO\E/?}{};
  return $d;
}

find({ wanted => sub {
  return unless /\.go$/;
  my $fp = $File::Find::name;
  return if is_store($fp);
  open my $fh, "<", $fp or return;
  local $/; my $c = <$fh>; close $fh;
  my $pkg = pkg_of($fp);
  my $rel = $fp; $rel =~ s{^\Q$REPO\E/?}{};
  for my $t (@ENTITIES) {
    next unless $c =~ /\bstore\.$t\b/;
    $hits{$t}{$pkg}{$rel} = 1;
  }
}, no_chdir => 1 }, $REPO);

print "=" x 70, "\nCORE ENTITY TYPES\n", "=" x 70, "\n";
my @ranked = sort { scalar(keys %{$hits{$b}}) <=> scalar(keys %{$hits{$a}}) } @ENTITIES;
for my $t (@ranked) {
  my @pkgs = sort keys %{$hits{$t}};
  print "\n$t: ", scalar(@pkgs), " packages\n";
  for my $p (@pkgs) {
    my @files = sort keys %{$hits{$t}{$p}};
    print "  [$p] (", scalar(@files), " files)\n";
    print "    - $_\n" for @files;
  }
}
'

